CREATE TABLE public.occurrence_contestations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid NOT NULL REFERENCES public.occurrences(id),body text NOT NULL CHECK(length(trim(body))>0),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid REFERENCES public.profiles(id),decision text CHECK(decision IN ('uphold','reopen')),reason text);
GRANT SELECT ON public.occurrence_contestations TO authenticated; GRANT ALL ON public.occurrence_contestations TO service_role;
ALTER TABLE public.occurrence_contestations ENABLE ROW LEVEL SECURITY;
CREATE POLICY contestation_read ON public.occurrence_contestations FOR SELECT TO authenticated USING(public.has_occurrence_access(occurrence_id));
CREATE UNIQUE INDEX one_pending_contestation ON public.occurrence_contestations(occurrence_id) WHERE reviewed_at IS NULL;
CREATE FUNCTION public.submit_unfounded_contestation(p_occurrence_id uuid,p_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.occurrences; cid uuid; BEGIN IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Contestação exclusiva do cliente por link validado'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=p_occurrence_id FOR UPDATE; IF o.status<>'closed_unfounded' OR length(trim(coalesce(p_body,'')))=0 THEN RAISE EXCEPTION 'Contestação não permitida'; END IF; INSERT INTO public.occurrence_contestations(occurrence_id,body) VALUES(o.id,trim(p_body)) RETURNING id INTO cid; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,body,metadata) VALUES(o.id,'customer_reply','customer',trim(p_body),jsonb_build_object('action','unfounded_contestation','contestation_id',cid)); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.submit_unfounded_contestation(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_unfounded_contestation(uuid,text) TO service_role;
CREATE FUNCTION public.review_unfounded_contestation(p_id uuid,p_decision text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.occurrence_contestations; o public.occurrences; a public.accounts; t public.sla_targets; BEGIN SELECT * INTO STRICT c FROM public.occurrence_contestations WHERE id=p_id FOR UPDATE; IF NOT public.has_occurrence_access(c.occurrence_id) OR coalesce(public.current_app_role() NOT IN ('kam','ops_manager'),true) THEN RAISE EXCEPTION 'Revisão exclusiva de KAM ou gestor'; END IF; SELECT * INTO STRICT o FROM public.occurrences WHERE id=c.occurrence_id FOR UPDATE; IF c.reviewed_at IS NOT NULL OR o.status<>'closed_unfounded' OR p_decision NOT IN ('uphold','reopen') OR length(trim(coalesce(p_reason,'')))=0 THEN RAISE EXCEPTION 'Revisão não permitida'; END IF; IF p_decision='reopen' THEN SELECT * INTO STRICT a FROM public.accounts WHERE id=o.account_id; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=o.severity; UPDATE public.occurrences SET status='reopened',reopen_count=reopen_count+1,resolution_started_at=now(),resolution_due_at=public.add_business_minutes(a.calendar_id,now(),t.resolution_minutes),paused_business_minutes=0,paused_since=NULL,paused_from_status=NULL,solution_proposed_at=NULL,closed_at=NULL,next_update_due_at=public.add_business_minutes(a.calendar_id,now(),t.update_interval_minutes) WHERE id=o.id; END IF; UPDATE public.occurrence_contestations SET reviewed_at=now(),reviewed_by=auth.uid(),decision=p_decision,reason=trim(p_reason) WHERE id=c.id; INSERT INTO public.occurrence_events(occurrence_id,kind,visibility,author_id,body,from_status,to_status,metadata) VALUES(o.id,'system','system',auth.uid(),trim(p_reason),o.status,CASE WHEN p_decision='reopen' THEN 'reopened'::public.occ_status ELSE o.status END,jsonb_build_object('action','contestation_review','decision',p_decision,'contestation_id',c.id)); END $$;
REVOKE ALL ON FUNCTION public.review_unfounded_contestation(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_unfounded_contestation(uuid,text,text) TO authenticated;
COMMENT ON FUNCTION public.submit_unfounded_contestation(uuid,text) IS 'Server-only primitive; public handler must verify customer token and rate limits. Does not reopen or restart SLA.';